def minPath(grid, k):
    m, n = len(grid), len(grid[0])
    dp = [[float('inf')] * n for _ in range(m)]
    dp[0][0] = 0

    # Initialize the first row and column
    for i in range(1, m):
        if grid[i][0] == 0:
            dp[i][0] = dp[i-1][0] + 1
    for j in range(1, n):
        if grid[0][j] == 0:
            dp[0][j] = dp[0][j-1] + 1

    # Fill the DP table
    for i in range(1, m):
        for j in range(1, n):
            if grid[i][j] == 0:
                dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + 1

    # Construct the result list
    result = [0] * k
    for i in range(k):
        if i % 2 == 0:
            result[i] = dp[m-1][n-1]
        else:
            result[i] = 1

